func (o *ItemAllocation) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Pool":
		rel, ok := retrieved.(*Pool)
		if !ok {
			return fmt.Errorf("itemAllocation cannot load %T as %q", retrieved, name)
		}

		o.R.Pool = rel
		o.R.Loaded.Pool = true

		if rel != nil {
			rel.R.ItemAllocations = ItemAllocationSlice{o}
		}
		return nil
	case "PurchaseItem":
		rel, ok := retrieved.(*PurchaseItem)
		if !ok {
			return fmt.Errorf("itemAllocation cannot load %T as %q", retrieved, name)
		}

		o.R.PurchaseItem = rel
		o.R.Loaded.PurchaseItem = true

		if rel != nil {
			rel.R.ItemAllocations = ItemAllocationSlice{o}
		}
		return nil
	case "AllocationRule":
		rel, ok := retrieved.(*AllocationRule)
		if !ok {
			return fmt.Errorf("itemAllocation cannot load %T as %q", retrieved, name)
		}

		o.R.AllocationRule = rel
		o.R.Loaded.AllocationRule = true

		if rel != nil {
			rel.R.ItemAllocations = ItemAllocationSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("itemAllocation has no relationship %q", name)
	}
}

