// LoadPool loads the itemAllocation's Pool into the .R struct
func (o *ItemAllocation) LoadPool(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Pool = nil
	o.R.Loaded.Pool = false

	related, err := o.Pool(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.ItemAllocations = ItemAllocationSlice{o}

	o.R.Pool = related
	o.R.Loaded.Pool = true
	return nil
}

// LoadPool loads the itemAllocation's Pool into the .R struct
func (os ItemAllocationSlice) LoadPool(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	pools, err := os.Pool(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Pool = nil
		o.R.Loaded.Pool = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range pools {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.PoolID == rel.ID) {
				continue
			}

			rel.R.ItemAllocations = append(rel.R.ItemAllocations, o)

			o.R.Pool = rel
			break
		}
	}

	return nil
}

